UPDATE qcm_report
report_name = #{reportName}, report_type = #{reportType}, report_date = #{reportDate}, instrument_name = #{instrumentName}, instrument_no = #{instrumentNo}, gas_type = #{gasType}, filer = #{filer}, reviewer = #{reviewer}, maintenance_company = #{maintenanceCompany}, report_note = #{reportNote}, is_discarded = #{isDiscarded}, updated_by = #{updatedBy}, update_time = #{updateTime,typeHandler=com.ecat.integration.EnvQualityControlManagerIntegration.support.TimestamptzInstantTypeHandler,jdbcType=TIMESTAMP}, gas_source = #{gasSource}, gas_no = #{gasNo},
WHERE id = #{id}
